import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import test from 'node:test';

test('contains intentionally wrong knowledge and current evidence', async () => {
  const source = await readFile(new URL('../src/rollout.ts', import.meta.url), 'utf8');
  const runtime = await readFile(new URL('../config/runtime-observation.txt', import.meta.url), 'utf8');
  const guide = await readFile(new URL('../.agents/knowledge/guides/rollout.md', import.meta.url), 'utf8');
  assert.match(source, /rollout = 25/);
  assert.match(runtime, /rollout_percent=25/);
  assert.match(guide, /percentage is 90/);
});
